sys_script_include.script:
var PercentCompleteCalc = Class.create();
PercentCompleteCalc.prototype = {
    initialize: function() {
    },

	recalcParent: function(parentSysId) { 

		gs.info("[PercentCompleteCalc] Starting recalculation for parent: " + parentSysId);

		if (!parentSysId) {
			gs.warn("[PercentCompleteCalc] No parentSysId provided. Exiting.");
			return; 
		} 

		var totalHours = 0; 
		var completedHours = 0;

		var childGR = new GlideRecord('x_942105_12_week_y_daily_tactic'); 
		childGR.addQuery('weekly_action', parentSysId); 
		childGR.query();

		while (childGR.next()) { 
			count++;

			var hours = parseFloat(childGR.time_estimate || 0); 
			totalHours += hours; 

			gs.info("[PercentCompleteCalc] Child: " + childGR.getUniqueValue() +
                    " | Hours: " + hours +
                    " | Complete: " + childGR.completed);

			if (childGR.completed == true || childGR.completed == 'true') { 
				completedHours += hours; 
			} 
		}

		gs.info("[PercentCompleteCalc] Total children found: " + count);
        gs.info("[PercentCompleteCalc] Total Hours: " + totalHours);
        gs.info("[PercentCompleteCalc] Completed Hours: " + completedHours);

		// Calculate percent complete 
		var percentComplete = 0; 
		if (totalHours > 0) { 
			percentComplete = (completedHours / totalHours) * 100; 
		}

		// Round to 2 decimal places 
		percentComplete = parseFloat(percentComplete.toFixed(2)); 

		gs.info("[PercentCompleteCalc] Percent Complete calculated: " + percentComplete + "%");

		// Update parent 
		var parentGR = new GlideRecord('x_942105_12_week_y_weekly_action'); 
		if (parentGR.get(parentSysId)) { 

			gs.info("[PercentCompleteCalc] Updating parent record: " + parentSysId);

			parentGR.time_estimate = totalHours; 
			parentGR.u_percent_complete = percentComplete; 

			var updateResult = parentGR.update(); 
			gs.info("[PercentCompleteCalc] Parent update result: " + updateResult);

        } else {
            gs.error("[PercentCompleteCalc] Failed to retrieve parent record: " + parentSysId);
		} 
	},

    type: 'PercentCompleteCalc'
};
